// ============= URL Param Helpers =============
const SAVED_VIEW_PARAM = "saved_view";

function readSavedViewFromUrl(): string | null {
  if (typeof window === "undefined") return null;
  const params = new URLSearchParams(window.location.search);
  return params.get(SAVED_VIEW_PARAM);
}

function writeSavedViewToUrl(viewId: string | null): void {
  if (typeof window === "undefined") return;
  const params = new URLSearchParams(window.location.search);
  if (viewId) {
    params.set(SAVED_VIEW_PARAM, viewId);
  } else {
    params.delete(SAVED_VIEW_PARAM);
  }
  const qs = params.toString();
  const url = qs
    ? `${window.location.pathname}?${qs}`
    : window.location.pathname;
  window.history.replaceState(null, "", url);
}

// ============= Filter Mapping Helpers =============

/** Map SavedViewFilterParams → FilterState (for applying view to UI) */
function mapToFilterState(filters: SavedViewFilterParams): FilterState {
  const state: FilterState = {};
  if (filters.priority !== undefined) state.priority = filters.priority as Priority;
  if (filters.type !== undefined) state.type = filters.type as IssueType;
  if (filters.labels !== undefined && filters.labels.length > 0) {
    state.labels = filters.labels;
  }
  // SavedViewFilterParams fields that don't map to FilterState:
  // status, assignee, unassigned, labels_any, limit, sort_policy,
  // parent_id, mol_type, include_deferred, include_mol_steps, source_repos
  // → These are used by task .8 when building WorkFilter, not here
  return state;
}

/** Map FilterState → SavedViewFilterParams (for saving current state as view) */
function mapFromFilterState(state: FilterState): SavedViewFilterParams {
  const filters: SavedViewFilterParams = {};
  if (state.priority !== undefined) filters.priority = state.priority;
  if (state.type !== undefined) filters.type = state.type;
  if (state.labels !== undefined && state.labels.length > 0) {
    filters.labels = state.labels;
  }
  return filters;
}
