**Hook implementation (pseudocode with key logic):**

```typescript
const REFETCH_DEBOUNCE_MS = 100;

export function useSavedViews(options: UseSavedViewsOptions): UseSavedViewsReturn {
  const { filterState, filterActions, autoFetch = true } = options;

  // ---- State ----
  const [views, setViews] = useState<SavedView[]>([]);
  const [activeViewId, setActiveViewId] = useState<string | null>(
    () => readSavedViewFromUrl()
  );
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // ---- Refs ----
  const mountedRef = useRef(true);
  const refetchDebounceRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  /** FilterState derived from the last applied view — comparison target */
  const appliedViewFilters = useRef<FilterState | null>(null);
  /** Skip one deactivation check after applyView (prevents self-deactivation) */
  const skipDeactivationRef = useRef(false);
  /** Tracks whether initial view application from URL has been attempted */
  const initialApplyDoneRef = useRef(false);
  // Store filterActions in ref to avoid stale closure in applyView
  const filterActionsRef = useRef(filterActions);

  useEffect(() => { filterActionsRef.current = filterActions; }, [filterActions]);

  // ---- Cleanup ----
  useEffect(() => {
    mountedRef.current = true;
    return () => {
      mountedRef.current = false;
      if (refetchDebounceRef.current) clearTimeout(refetchDebounceRef.current);
    };
  }, []);

  // ---- Fetch ----
  const refetch = useCallback(async () => {
    if (!mountedRef.current) return;
    setIsLoading(true);
    setError(null);
    try {
      const data = await listSavedViews();
      if (mountedRef.current) setViews(data);
    } catch (err) {
      if (mountedRef.current) {
        setError(err instanceof Error ? err.message : "Failed to fetch saved views");
      }
    } finally {
      if (mountedRef.current) setIsLoading(false);
    }
  }, []);

  // Auto-fetch on mount
  useEffect(() => {
    if (autoFetch) void refetch();
  }, [autoFetch, refetch]);

  // ---- SSE Mutation Handler (useIssueTabPersistence pattern) ----
  const handleMutation = useCallback((mutation: MutationPayload) => {
    if (mutation.type !== "saved_views_changed") return;
    if (refetchDebounceRef.current) clearTimeout(refetchDebounceRef.current);
    refetchDebounceRef.current = setTimeout(() => {
      void refetch();
    }, REFETCH_DEBOUNCE_MS);
  }, [refetch]);

  // ---- Deactivation (internal) ----
  const deactivateViewInternal = useCallback(() => {
    setActiveViewId(null);
    appliedViewFilters.current = null;
    writeSavedViewToUrl(null);
  }, []);

  // ---- Apply View ----
  const applyView = useCallback((view: SavedView) => {
    // 1. Set skip flag BEFORE calling filterActions
    skipDeactivationRef.current = true;

    // 2. Derive FilterState from view's filters
    const targetFilterState = mapToFilterState(view.filters);

    // 3. Store as comparison reference
    appliedViewFilters.current = targetFilterState;

    // 4. Apply via filterActions — clearAll first, then set each field
    //    React 18 batches all synchronous setState calls into one render
    const actions = filterActionsRef.current;
    actions.clearAll();
    if (targetFilterState.priority !== undefined) actions.setPriority(targetFilterState.priority);
    if (targetFilterState.type !== undefined) actions.setType(targetFilterState.type);
    if (targetFilterState.labels !== undefined) actions.setLabels(targetFilterState.labels);

    // 5. Update active view ID and URL param
    setActiveViewId(view.id);
    writeSavedViewToUrl(view.id);
  }, []);

  // ---- Auto-Deactivation Effect ----
  useEffect(() => {
    // Skip if we just applied a view
    if (skipDeactivationRef.current) {
      skipDeactivationRef.current = false;
      return;
    }
    // Only check when a view is active
    if (!activeViewId || !appliedViewFilters.current) return;
    // Compare current filter state with what the view applied
    if (JSON.stringify(filterState) !== JSON.stringify(appliedViewFilters.current)) {
      deactivateViewInternal();
    }
  }, [filterState, activeViewId, deactivateViewInternal]);

  // ---- Initial View Application from URL ----
  // After views are fetched and we have an activeViewId from URL, apply the view
  useEffect(() => {
    if (initialApplyDoneRef.current) return;
    if (views.length === 0 || !activeViewId) return;

    initialApplyDoneRef.current = true;
    const view = views.find(v => v.id === activeViewId);
    if (view) {
      applyView(view);
    } else {
      // View no longer exists — clear stale URL param
      deactivateViewInternal();
    }
  }, [views, activeViewId, applyView, deactivateViewInternal]);

  // ---- Popstate Handler (browser back/forward) ----
  useEffect(() => {
    if (typeof window === "undefined") return;
    const handlePopState = () => {
      const urlViewId = readSavedViewFromUrl();
      if (urlViewId !== activeViewId) {
        if (urlViewId) {
          const view = views.find(v => v.id === urlViewId);
          if (view) applyView(view);
          else deactivateViewInternal();
        } else {
          deactivateViewInternal();
        }
      }
    };
    window.addEventListener("popstate", handlePopState);
    return () => window.removeEventListener("popstate", handlePopState);
  }, [activeViewId, views, applyView, deactivateViewInternal]);

  // ---- CRUD Operations ----
  const createView = useCallback(async (req: CreateSavedViewRequest): Promise<SavedView> => {
    const created = await createSavedView(req);
    await refetch(); // Refetch list to include new view
    return created;
  }, [refetch]);

  const updateView = useCallback(async (viewId: string, req: UpdateSavedViewRequest): Promise<SavedView> => {
    const updated = await apiUpdateSavedView(viewId, req);
    await refetch();
    // If the active view was updated, re-apply its filters
    if (viewId === activeViewId) {
      const refreshed = views.find(v => v.id === viewId);
      // Use updated data if refetch already populated it, otherwise use the response
      const viewToApply = refreshed ?? updated;
      applyView(viewToApply);
    }
    return updated;
  }, [refetch, activeViewId, views, applyView]);

  const deleteView = useCallback(async (viewId: string): Promise<void> => {
    await apiDeleteSavedView(viewId);
    // If the deleted view was active, deactivate
    if (viewId === activeViewId) {
      deactivateViewInternal();
    }
    await refetch();
  }, [refetch, activeViewId, deactivateViewInternal]);

  const reorderViews = useCallback(async (ids: string[]): Promise<SavedView[]> => {
    const reordered = await apiReorderSavedViews({ ids });
    await refetch();
    return reordered;
  }, [refetch]);

  const saveCurrentAsView = useCallback(async (name: string, description?: string): Promise<SavedView> => {
    const filters = mapFromFilterState(filterState);
    const created = await createSavedView({ name, description, filters });
    await refetch();
    // Auto-activate the newly created view
    applyView(created);
    return created;
  }, [filterState, refetch, applyView]);

  // ---- Deactivate View (public) ----
  const deactivateView = useCallback(() => {
    deactivateViewInternal();
  }, [deactivateViewInternal]);

  return {
    views,
    activeViewId,
    isLoading,
    error,
    applyView,
    deactivateView,
    createView,
    updateView,
    deleteView,
    reorderViews,
    saveCurrentAsView,
    refetch,
    handleMutation,
  };
}
```

