### \`internal/webui/frontend/src/api/sessions.ts\`
Four API client functions:

\`\`\`typescript
import { ApiError, get, getAuthToken } from "./client";
import type {
  SessionRecord,
  SessionListResponse,
  SessionDetailResponse,
  TranscriptEntry,
  TranscriptResponse,
} from "@/types/session";

/**
 * Fetch all sessions for a task.
 * Returns empty array for unknown tasks (graceful degradation).
 */
export async function getTaskSessions(taskId: string): Promise<SessionRecord[]> {
  let response: SessionListResponse;
  try {
    response = await get<SessionListResponse>(
      \`/api/tasks/\${encodeURIComponent(taskId)}/sessions\`
    );
  } catch (err) {
    if (err instanceof ApiError && err.status === 404) {
      return [];
    }
    throw err;
  }
  return response.data?.sessions ?? [];
}

/**
 * Fetch session detail metadata.
 */
export async function getSession(
  taskId: string,
  sessionId: string,
): Promise<SessionDetailResponse["data"]> {
  const response = await get<SessionDetailResponse>(
    \`/api/tasks/\${encodeURIComponent(taskId)}/sessions/\${encodeURIComponent(sessionId)}\`
  );
  return response.data;
}

/**
 * Fetch session transcript entries.
 * Returns empty entries array on 404 (graceful degradation).
 */
export async function getSessionTranscript(
  taskId: string,
  sessionId: string,
): Promise<TranscriptEntry[]> {
  let response: TranscriptResponse;
  try {
    response = await get<TranscriptResponse>(
      \`/api/tasks/\${encodeURIComponent(taskId)}/sessions/\${encodeURIComponent(sessionId)}/transcript\`
    );
  } catch (err) {
    if (err instanceof ApiError && err.status === 404) {
      return [];
    }
    throw err;
  }
  return response.data?.entries ?? [];
}

/**
 * Fetch session diff as raw text.
 * Uses raw fetch since the endpoint returns text/plain, not JSON.
 * Returns empty string on 404.
 */
export async function getSessionDiff(
  taskId: string,
  sessionId: string,
): Promise<string> {
  const headers: Record<string, string> = {};
  const token = getAuthToken();
  if (token) {
    headers["Authorization"] = \`Bearer \${token}\`;
  }

  const response = await fetch(
    \`/api/tasks/\${encodeURIComponent(taskId)}/sessions/\${encodeURIComponent(sessionId)}/diff\`,
    { headers },
  );

  if (!response.ok) {
    if (response.status === 404) {
      return "";
    }
    throw new Error(\`Failed to fetch session diff: \${response.status}\`);
  }

  return response.text();
}
