Extract the three formatting functions currently in SessionTimelineRow.tsx:

```typescript
/** Format duration in seconds to "Xm Ys" or "Xh Ym" */
export function formatDuration(seconds: number | undefined): string {
  if (seconds == null || seconds <= 0) return "--";
  if (seconds >= 3600) {
    const h = Math.floor(seconds / 3600);
    const m = Math.round((seconds % 3600) / 60);
    return m > 0 ? \`\${h}h \${m}m\` : \`\${h}h\`;
  }
  const m = Math.floor(seconds / 60);
  const s = Math.round(seconds % 60);
  if (m === 0) return \`\${s}s\`;
  return \`\${m}m \${s}s\`;
}

/** Format token count with K/M suffix */
export function formatTokens(count: number): string {
  if (count >= 1_000_000) return \`\${(count / 1_000_000).toFixed(1)}M\`;
  if (count >= 1_000) return \`\${(count / 1000).toFixed(1)}K\`;
  return String(count);
}

/** Format USD cost */
export function formatCost(usd: number): string {
  if (usd === 0) return "\$0.00";
  if (usd < 0.01) return "<\$0.01";
  return \`\$\${usd.toFixed(2)}\`;
}
```

Note: formatDuration is enhanced to handle hours (the total across all sessions can easily exceed 60 minutes). The original in SessionTimelineRow only handles minutes — that's fine for a single session but not for aggregates.

