```go
package cli

import (
    "encoding/json"
    "fmt"
    "strconv"
)

// bdBackend implements IssueTracker by shelling out to the bd CLI via BDRunner.
type bdBackend struct {
    runner BDRunner
    dir    string
}

func newBdBackend(runner BDRunner, dir string) *bdBackend {
    return &bdBackend{runner: runner, dir: dir}
}

// --- IssueBackend (Phase 1 shim) ---

func (b *bdBackend) RunCommand(args ...string) (string, error) {
    result := b.runner.Run(b.dir, args...)
    if result.Err != nil {
        return "", result.Err
    }
    return result.Stdout, nil
}

// --- Query methods ---

func (b *bdBackend) Ready(opts ReadyOpts) ([]BdIssue, error) {
    args := []string{"ready", "--json"}
    if opts.Limit > 0 {
        args = append(args, "--limit", strconv.Itoa(opts.Limit))
    }
    if opts.ParentID != "" {
        args = append(args, "--parent", opts.ParentID)
    }
    return b.queryIssues("Ready", args)
}

func (b *bdBackend) List(opts ListOpts) ([]BdIssue, error) {
    args := []string{"list", "--json"}
    if opts.Status != "" {
        args = append(args, "--status", opts.Status)
    }
    if opts.Assignee != "" {
        args = append(args, "--assignee", opts.Assignee)
    }
    if opts.Type != "" {
        args = append(args, "--type", opts.Type)
    }
    if opts.Limit > 0 {
        args = append(args, "--limit", strconv.Itoa(opts.Limit))
    }
    return b.queryIssues("List", args)
}

func (b *bdBackend) Blocked() ([]BdIssue, error) {
    return b.queryIssues("Blocked", []string{"blocked", "--json"})
}

func (b *bdBackend) Stats() (*BdStats, error) {
    result := b.runner.Run(b.dir, "stats", "--json")
    if result.Err != nil {
        return nil, fmt.Errorf("bdBackend.Stats: %w", result.Err)
    }
    var stats BdStats
    if err := json.Unmarshal([]byte(result.Stdout), &stats); err != nil {
        return nil, fmt.Errorf("bdBackend.Stats: parse: %w", err)
    }
    return &stats, nil
}

func (b *bdBackend) GetIssue(id string) (*BdIssue, error) {
    result := b.runner.Run(b.dir, "show", id, "--json")
    if result.Err != nil {
        return nil, fmt.Errorf("bdBackend.GetIssue(%s): %w", id, result.Err)
    }
    // bd show --json returns a single-element array
    var issues []BdIssue
    if err := json.Unmarshal([]byte(result.Stdout), &issues); err != nil {
        return nil, fmt.Errorf("bdBackend.GetIssue(%s): parse: %w", id, err)
    }
    if len(issues) == 0 {
        return nil, fmt.Errorf("bdBackend.GetIssue(%s): not found", id)
    }
    return &issues[0], nil
}

func (b *bdBackend) GetIssueText(id string) (string, error) {
    // No --json flag: returns human-readable output
    result := b.runner.Run(b.dir, "show", id)
    if result.Err != nil {
        return "", fmt.Errorf("bdBackend.GetIssueText(%s): %w", id, result.Err)
    }
    return result.Stdout, nil
}

// --- Mutation methods ---

func (b *bdBackend) UpdateStatus(id, status string) error {
    return b.runMutation("UpdateStatus", "update", id, "--status", status)
}

func (b *bdBackend) UpdateExternalRef(id, ref string) error {
    return b.runMutation("UpdateExternalRef", "update", id, "--external-ref", ref)
}

func (b *bdBackend) CloseIssue(id, reason string) error {
    return b.runMutation("CloseIssue", "close", id, "--reason", reason)
}

func (b *bdBackend) SyncStatus() error {
    return b.runMutation("SyncStatus", "sync", "--status")
}

// --- Metadata ---

func (b *bdBackend) BackendName() string {
    return "beads"
}

// --- internal helpers ---

func (b *bdBackend) queryIssues(method string, args []string) ([]BdIssue, error) {
    result := b.runner.Run(b.dir, args...)
    if result.Err != nil {
        return nil, fmt.Errorf("bdBackend.%s: %w", method, result.Err)
    }
    var issues []BdIssue
    if err := json.Unmarshal([]byte(result.Stdout), &issues); err != nil {
        return nil, fmt.Errorf("bdBackend.%s: parse: %w", method, err)
    }
    return issues, nil
}

func (b *bdBackend) runMutation(method string, args ...string) error {
    result := b.runner.Run(b.dir, args...)
    if result.Err != nil {
        return fmt.Errorf("bdBackend.%s: %w", method, result.Err)
    }
    return nil
}
```

