export function DiffViewer({ agentName, enabled = true }: DiffViewerProps) {
  const diff = useDiff({ agentName, enabled });

  if (diff.commitsLoading && diff.commits.length === 0) {
    return <div className={styles.loading}>Loading commits…</div>;
  }

  if (diff.commitsError) {
    return <div className={styles.error}>Failed to load commits: {diff.commitsError.message}</div>;
  }

  if (diff.commits.length === 0) {
    return <div className={styles.empty}>No commits found for this agent.</div>;
  }

  return (
    <div className={styles.root}>
      <CommitSelector
        commits={diff.commits}
        selectedFrom={diff.selectedFrom}
        selectedTo={diff.selectedTo}
        onSelectFrom={diff.setSelectedFrom}
        onSelectTo={diff.setSelectedTo}
        onSelectSingle={diff.selectSingleCommit}
        onPrev={diff.goPrev}
        onNext={diff.goNext}
        canPrev={diff.canGoPrev}
        canNext={diff.canGoNext}
      />
      <div className={styles.body}>
        <DiffFileTree
          files={diff.files}
          loading={diff.filesLoading}
          selectedPath={diff.selectedFilePath}
          onSelectFile={diff.setSelectedFilePath}
          reviewedPaths={diff.reviewedPaths}
          onToggleReviewed={diff.toggleReviewed}
          reviewProgress={diff.reviewProgress}
        />
        <DiffFilePanel
          filePatch={diff.filePatch}
          loading={diff.filePatchLoading}
          error={diff.filePatchError}
          selectedPath={diff.selectedFilePath}
          comments={diff.selectedFilePath ? diff.getCommentsForFile(diff.selectedFilePath) : []}
          onAddComment={diff.addComment}
          onRemoveComment={diff.removeComment}
        />
      </div>
    </div>
  );
}
