Concrete implementation. Imports \`webui\` (not the other way around):
\`\`\`go
package cli

import \"github.com/tysonthomas9/loomcli/internal/webui\"

type BackendOpsImpl struct{}

func NewBackendOps() *BackendOpsImpl { return &BackendOpsImpl{} }

func (b *BackendOpsImpl) ListBackendsHealth() ([]webui.BackendHealth, error) {
    names := ListBackends()
    result := make([]webui.BackendHealth, 0, len(names))
    for _, name := range names {
        backend, ok := GetBackendByName(name)
        if !ok { continue }
        entry := webui.BackendHealth{Name: name, Available: true, Installed: true, APIKeySet: true}
        caps := InspectCapabilities(backend)
        if caps.HasMeta {
            meta := caps.Meta.Meta()
            entry.DisplayName = meta.DisplayName
            entry.Version = meta.Version
        }
        if caps.HasHealthCheck {
            health := caps.Health.HealthCheck()
            entry.Installed = health.Installed
            entry.APIKeySet = health.APIKeySet
            entry.Available = health.Installed && health.APIKeySet
            entry.Version = health.Version
            entry.Message = health.Message
        }
        result = append(result, entry)
    }
    return result, nil
}
\`\`\`

