frontend-ensure:
	@if [ ! -d $(FRONTEND_DIR)/dist ]; then echo "frontend/dist missing — building..."; $(MAKE) frontend; fi
```

b) Add `check-go` target — Go-only quality gates (steps 1-7), depends on `frontend-ensure`:
