	if [ -n "$$bad" ]; then echo "gofmt violations:"; echo "$$bad"; exit 1; fi
	@echo "=== [2/7] Go: vet ==="
	@go vet ./...
	@echo "=== [3/7] Go: build ==="
	@go build ./...
	@echo "=== [4/7] Go: lint (golangci-lint + depguard) ==="
