// Ctrl+Tab / Ctrl+Shift+Tab: cycle tabs
// Also Alt+ArrowRight / Alt+ArrowLeft as Firefox-compatible fallback
// (Firefox intercepts Ctrl+Tab at the browser level — e.preventDefault() cannot override it)
if (
  (e.ctrlKey && e.key === "Tab") ||
  (e.altKey && (e.key === "ArrowRight" || e.key === "ArrowLeft"))
) {
  e.preventDefault();
  const goForward = e.key === "Tab" ? !e.shiftKey : e.key === "ArrowRight";
  setTabs(prev => {
    if (prev.length <= 1) return prev;
    const currentIdx = prev.findIndex(t => t.id === activeTabIdRef.current);
    const nextIdx = goForward
      ? (currentIdx < prev.length - 1 ? currentIdx + 1 : 0)
      : (currentIdx > 0 ? currentIdx - 1 : prev.length - 1);
    setActiveTabId(prev[nextIdx].id);
    return prev;
  });
  return;
}

// Escape: return to previous view when nothing else to dismiss
