```typescript
interface TabState {
  id: string;               // unique tab identifier (same as sessionName)
  label: string;            // display label from TerminalSessionInfo.label
  sessionName: string;      // tmux session name (from TerminalSessionInfo.name)
  connectionState: ConnectionState;
}

// Hook provides initial sessions
