## Summary

Create `api/terminal.ts` as a new API client module for terminal-related endpoints, and `hooks/useTerminalSessions.ts` as a React hook that fetches terminal sessions on mount. This extracts the inline `fetchTerminalToken()` and `buildWsUrl()` functions from TerminalPanel.tsx into a dedicated API module, and adds a new `listTerminalSessions()` function that calls the `GET /api/terminal/sessions` endpoint (from task jcr0g.1). The hook provides the session list with loading/error states and a hardcoded "talk-to-lead" fallback if the API fails.

## Technical Approach

Follow the established patterns from `api/config.ts` (API module) and `hooks/useBackendConfig.ts` (hook). The API module uses `get()` from `api/client.ts` with typed generics and the `ApiResult<T>` / `unwrap()` pattern. The hook uses `useState`/`useCallback`/`useEffect`/`useRef` with `mountedRef` for safe unmount handling.

Key decisions:
- `fetchTerminalToken()` and `buildTerminalWsUrl()` accept a `sessionName` parameter instead of hardcoding `TERMINAL_SESSION`, making them reusable for multi-tab terminals
- The hook returns a default `[{ name: "talk-to-lead", label: "talk-to-lead", created: 0 }]` on API failure, matching the backend's guarantee
- No polling — sessions are fetched once on mount with a `refetch()` escape hatch; polling can be added later if needed

## Files to Create

### 1. `internal/webui/frontend/src/api/terminal.ts`
Terminal API client module containing:

```typescript
import { get, ApiError } from "./client";

// ============= Types =============

export interface TerminalSessionInfo {
  name: string;    // e.g. "talk-to-lead"
  label: string;   // display label
  created: number; // Unix timestamp, 0 if not yet created
}

// ============= Response Types =============

interface ApiSuccess<T> {
  success: true;
  data: T;
}

interface ApiFailure {
  success: false;
  error: string;
}

type ApiResult<T> = ApiSuccess<T> | ApiFailure;

function unwrap<T>(response: ApiResult<T>): T {
  if (!response.success) {
    throw new ApiError(0, response.error);
  }
  return response.data;
}

// ============= API Functions =============

/**
 * List active terminal sessions from GET /api/terminal/sessions.
 */
export async function listTerminalSessions(): Promise<TerminalSessionInfo[]> {
  const response = await get<ApiResult<{ sessions: TerminalSessionInfo[] }>>(
    "/api/terminal/sessions",
  );
  return unwrap(response).sessions;
}

/**
 * Fetch a one-time terminal auth token for the given session.
 * Returns null on failure (WebSocket will be rejected by server).
 */
export async function fetchTerminalToken(
  sessionName: string,
): Promise<string | null> {
  try {
    const resp = await get<{ token: string }>(
      `/api/terminal/token?session=${encodeURIComponent(sessionName)}`, // allow-url
    );
    return resp.token;
  } catch {
    return null;
  }
}

/**
 * Build the WebSocket URL for the terminal relay endpoint.
 */
export function buildTerminalWsUrl(
  sessionName: string,
  token: string | null,
): string {
  const proto = window.location.protocol === "https:" ? "wss:" : "ws:";
  let url = `${proto}//${window.location.host}/api/terminal/ws?session=${encodeURIComponent(sessionName)}`; // allow-url
  if (token) {
    url += `&token=${encodeURIComponent(token)}`;
  }
  return url;
}
```

### 2. `internal/webui/frontend/src/hooks/useTerminalSessions.ts`
React hook for terminal session state:

```typescript
import { useState, useCallback, useEffect, useRef } from "react";
import { listTerminalSessions } from "@/api/terminal";
import type { TerminalSessionInfo } from "@/api/terminal";

const DEFAULT_SESSIONS: TerminalSessionInfo[] = [
  { name: "talk-to-lead", label: "talk-to-lead", created: 0 },
];

export interface UseTerminalSessionsReturn {
  sessions: TerminalSessionInfo[];
  isLoading: boolean;
  error: Error | null;
  refetch: () => Promise<void>;
}

export function useTerminalSessions(): UseTerminalSessionsReturn {
  const [sessions, setSessions] = useState<TerminalSessionInfo[]>(DEFAULT_SESSIONS);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<Error | null>(null);
  const mountedRef = useRef(true);

  useEffect(() => {
    mountedRef.current = true;
    return () => { mountedRef.current = false; };
  }, []);

  const fetchSessions = useCallback(async () => {
    setIsLoading(true);
    setError(null);
    try {
      const data = await listTerminalSessions();
      if (mountedRef.current) {
        setSessions(data.length > 0 ? data : DEFAULT_SESSIONS);
      }
    } catch (err) {
      if (mountedRef.current) {
        setError(err instanceof Error ? err : new Error(String(err)));
        // Keep DEFAULT_SESSIONS as fallback — don't clear sessions on error
      }
    } finally {
      if (mountedRef.current) {
        setIsLoading(false);
      }
    }
  }, []);

  useEffect(() => {
    fetchSessions();
  }, [fetchSessions]);

  return { sessions, isLoading, error, refetch: fetchSessions };
}
```

