import { Hono } from "hono";
import { cors } from "hono/cors";
import { serve } from "@hono/node-server";
import { auth, db, closeDb, dialect } from "./auth.js";
import { runMigrations } from "./db/migrate.js";
import { env } from "./lib/env.js";
import { logger } from "./lib/logger.js";
import { metrics, renderMetrics } from "./lib/metrics.js";
import { sql } from "drizzle-orm";

// ============================================================
// Main application server (public-facing, port from env.PORT)
// ============================================================
const app = new Hono();

// --- Middleware ---

// Request logging middleware
app.use("*", async (c, next) => {
  const start = Date.now();
  await next();
  const duration = Date.now() - start;
  // Skip health to avoid probe spam (matching Go pattern)
  if (c.req.path !== "/health") {
    logger.info("request", {
      method: c.req.method,
      path: c.req.path,
      status: c.res.status,
      duration_ms: duration,
      ip: c.req.header("x-forwarded-for") || c.req.header("x-real-ip") || "unknown",
    });
  }
});

// TLS enforcement warning (production only)
// Logs a warning when requests arrive without TLS termination.
// Rate-limited to one warning per 60 seconds to avoid log spam.
let lastTlsWarning = 0;
if (env.NODE_ENV === "production") {
  app.use("*", async (c, next) => {
    const proto = c.req.header("x-forwarded-proto");
    if (!proto || proto !== "https") {
      const now = Date.now();
      if (now - lastTlsWarning > 60_000) {
        lastTlsWarning = now;
        logger.warn("request received without TLS termination in production", {
          path: c.req.path,
          x_forwarded_proto: proto ?? "missing",
          hint: "ensure a reverse proxy provides HTTPS and sets X-Forwarded-Proto",
        });
      }
    }
    await next();
  });
}

// CORS middleware
app.use("/api/*", cors({
  origin: env.TRUSTED_ORIGINS.length > 0
    ? env.TRUSTED_ORIGINS
    : [new URL(env.BETTER_AUTH_URL).origin],
  allowMethods: ["GET", "POST", "PUT", "PATCH", "DELETE", "OPTIONS"],
  allowHeaders: ["Content-Type", "Authorization", "X-Requested-With"],
  credentials: true,
  maxAge: 86400,
}));

// --- Metrics counting middleware (auth routes only) ---
// Increments Prometheus counters based on auth response status.
// This is the fallback strategy — preferred over Better Auth hooks
// because the hook API may not cleanly support all counters. Response-
// status-based counting gives reliable observability regardless of
// Better Auth version changes.
app.use("/api/auth/*", async (c, next) => {
  await next();
  if (c.req.path.includes("/sign-in") && c.req.method === "POST") {
    metrics.signInAttempts.inc();
    if (c.res.status === 200) metrics.sessionCreated.inc();
  }
  if (c.req.path.endsWith("/token") && c.req.method === "POST" && c.res.status === 200) {
    metrics.tokenIssued.inc();
  }
  if (c.res.status === 429) {
    metrics.rateLimitTriggered.inc();
  }
});

// --- Routes ---

// Health check with DB ping
app.get("/health", async (c) => {
  try {
    await db.execute(sql`SELECT 1`);
    return c.json({ status: "ok" }, 200);
  } catch (err) {
    logger.error("health check failed", {
      error: err instanceof Error ? err.message : String(err),
    });
    return c.json({
      status: "degraded",
      error: err instanceof Error ? err.message : "database unreachable",
    }, 503);
  }
});

// Mount Better Auth handler for all auth routes
app.on(["GET", "POST"], "/api/auth/*", (c) => {
  return auth.handler(c.req.raw);
});

// ============================================================
// Internal metrics server (separate port, NOT public-facing)
// ============================================================
const metricsApp = new Hono();

metricsApp.get("/metrics", (c) => {
  c.header("Content-Type", "text/plain; version=0.0.4; charset=utf-8");
  return c.text(renderMetrics());
});

// ============================================================
// Server startup
// ============================================================
async function main() {
  // Run database migrations before accepting traffic
  await runMigrations(dialect, db);
  logger.info("database migrations complete");

  // Log configured providers
  const providers = Object.keys(auth.options.socialProviders || {});
  logger.info("auth service starting", {
    port: env.PORT,
    metricsPort: env.METRICS_PORT,
    providers,
    mode: providers.length > 0 ? "oauth" : "minimal",
  });

  // Start main public server
  const server = serve({
    fetch: app.fetch,
    port: env.PORT,
  }, (info) => {
    logger.info("auth service listening", { port: info.port });
  });

  // Start internal metrics server on separate port
  const metricsServer = serve({
    fetch: metricsApp.fetch,
    port: env.METRICS_PORT,
  }, (info) => {
    logger.info("metrics server listening (internal only)", { port: info.port });
  });

  // Graceful shutdown
  let shuttingDown = false;
  const shutdown = async (signal: string) => {
    if (shuttingDown) return; // prevent double-close
    shuttingDown = true;
    logger.info("shutdown initiated", { signal });
    server.close();
    metricsServer.close();
    await closeDb();
    logger.info("shutdown complete");
    process.exit(0);
  };

  process.on("SIGINT", () => shutdown("SIGINT"));
  process.on("SIGTERM", () => shutdown("SIGTERM"));
}

main().catch((err) => {
  logger.error("fatal startup error", {
    error: err instanceof Error ? err.message : String(err),
  });
  process.exit(1);
});
