**ExternalAuthProvider component:**

```typescript
export function ExternalAuthProvider({ children }: { children: ReactNode }): JSX.Element {
  const { data: session, isPending, error } = getUseSession()();
  const [authServiceDown, setAuthServiceDown] = useState(false);
  const tokenFetchedForSession = useRef<string | null>(null);

  // When session changes: acquire JWT via authClient.token()
  useEffect(() => {
    if (isPending) return; // still loading, don't act yet

    if (error) {
      // Network error reaching auth service (not just "no session")
      setAuthServiceDown(true);
      setAuthToken(null);
      setAuthState('failed');
      return;
    }

    setAuthServiceDown(false);

    if (session?.user) {
      // Session exists — acquire RS256 JWT via authClient.token()
      // Deduplicate: only fetch if session ID changed
      const sessionId = session.session?.id ?? 'active';
      if (tokenFetchedForSession.current === sessionId) return;
      tokenFetchedForSession.current = sessionId;

      getAuthClient()
        .token()
        .then(({ token }) => {
          if (token) {
            setAuthToken(token);
          } else {
            setAuthToken(null);
            setAuthState('failed');
          }
        })
        .catch(() => {
          setAuthToken(null);
          setAuthState('failed');
        });
    } else {
      // No session, no error — user is not logged in
      tokenFetchedForSession.current = null;
      setAuthToken(null);
    }
  }, [session, isPending, error]);

  // Listen for 'auth-token-expired' from fetchApi's 401 handler
  useEffect(() => {
    function handleTokenExpired() {
      tokenFetchedForSession.current = null; // allow re-fetch
      refreshJwt();
    }
    window.addEventListener('auth-token-expired', handleTokenExpired);
    return () => window.removeEventListener('auth-token-expired', handleTokenExpired);
  }, []);

  // Map Better Auth user to our AuthUser type
  const user: AuthUser | null = session?.user
    ? {
        id: session.user.id,
        name: session.user.name ?? '',
        email: session.user.email,
        image: session.user.image ?? undefined,
      }
    : null;

  const signIn = useCallback(async (provider: 'github' | 'google') => {
    // Store current URL for post-login redirect
    sessionStorage.setItem(
      'loom-auth-return-to',
      window.location.pathname + window.location.search
    );
    await getAuthClient().signIn.social({
      provider,
      callbackURL: window.location.origin,
    });
  }, []);

  const signOut = useCallback(async () => {
    await getAuthClient().signOut();
    window.dispatchEvent(new CustomEvent('auth-sign-out'));
    setAuthToken(null);
    setAuthState('none');
  }, []);

  const value: AuthContextValue = {
    mode: 'external',
    user,
    isLoading: isPending,
    isAuthenticated: !!session?.user,
    authServiceDown,
    signIn,
    signOut,
  };

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}
```

**NoAuthProvider component:**
