### 1. `internal/webui/frontend/src/components/AuthGate/AuthGate.tsx`
Main AuthGate component. Consumes `useAuth()` from `@/contexts/AuthContext`. Handles URL error param extraction, deep link restoration, and rendering decisions (null / LoginPage / children).

**Imports:**
- `useState`, `useEffect`, `useRef` from 'react'
- `useAuth` from '@/contexts/AuthContext'
- `LoginPage` from '@/components/LoginPage'

**Component logic:**

```typescript
export function AuthGate({ children }: { children: React.ReactNode }): JSX.Element | null {
  const { mode, isLoading, isAuthenticated, authServiceDown } = useAuth();
  const [oauthError, setOauthError] = useState<string | null>(null);
  const returnToHandled = useRef(false);

  // Extract ?error= from URL on mount (OAuth failure redirect)
  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const error = params.get('error');
    if (error) {
      setOauthError(error);
      window.history.replaceState({}, '', window.location.pathname);
    }
  }, []);

  // Restore deep link from sessionStorage after successful auth
  useEffect(() => {
    if (!isAuthenticated || returnToHandled.current) return;
    returnToHandled.current = true;

    try {
      const returnTo = sessionStorage.getItem('loom-auth-return-to');
      sessionStorage.removeItem('loom-auth-return-to');

      if (returnTo && returnTo.startsWith('/') && !returnTo.includes('://')) {
        window.history.replaceState({}, '', returnTo);
      }
    } catch {
      // sessionStorage unavailable (private browsing) — acceptable degradation
    }
  }, [isAuthenticated]);

  // Decision tree
  if (isLoading) return null;
  if (mode === 'external' && !isAuthenticated) {
    return (
      <LoginPage
        error={oauthError}
        onErrorClear={() => setOauthError(null)}
      />
    );
  }
  return <>{children}</>;
}
```

