### 1. `internal/webui/frontend/src/hooks/useFileTree.ts`

Tree navigation state management hook.

```typescript
/**
 * useFileTree - React hook for managing file tree navigation state.
 * Handles directory expansion/collapse, entry caching, file selection,
 * and filter text with debounce.
 */

import { useState, useCallback, useRef, useEffect } from "react";
import { listWorktreeDir } from "@/api/files";
import type { FileEntry } from "@/api/files";
import { useDebounce } from "./useDebounce";

export interface UseFileTreeReturn {
  /** Set of expanded directory paths */
  expanded: Set<string>;
  /** Cached directory entries keyed by path */
  treeData: Map<string, FileEntry[]>;
  /** Currently selected file path, null if none */
  selectedPath: string | null;
  /** Whether the root directory is currently loading */
  isLoading: boolean;
  /** Error from the last directory fetch, null if successful */
  error: string | null;
  /** Current filter text (raw, un-debounced) */
  filterText: string;
  /** Debounced filter text for use in rendering */
  debouncedFilterText: string;
  /** Toggle a directory open/closed. Fetches contents on first expand. */
  toggle: (dirPath: string) => Promise<void>;
  /** Load a directory's contents explicitly (e.g., refresh) */
  loadDir: (dirPath: string) => Promise<void>;
  /** Select a file by path */
  selectFile: (filePath: string | null) => void;
  /** Set the filter text */
  setFilterText: (text: string) => void;
}

export function useFileTree(agentName: string): UseFileTreeReturn {
  // --- State ---
  const [expanded, setExpanded] = useState<Set<string>>(new Set());
  const [treeData, setTreeData] = useState<Map<string, FileEntry[]>>(new Map());
  const [selectedPath, setSelectedPath] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [filterText, setFilterText] = useState<string>("");

  const debouncedFilterText = useDebounce(filterText, 200);

  // --- Refs ---
  const mountedRef = useRef<boolean>(true);

  useEffect(() => {
    mountedRef.current = true;
    return () => { mountedRef.current = false; };
  }, []);

  // --- Actions ---
  const loadDir = useCallback(async (dirPath: string): Promise<void> => {
    if (!agentName) return;
    try {
      const result = await listWorktreeDir(agentName, dirPath || undefined);
      if (mountedRef.current) {
        setTreeData(prev => {
          const next = new Map(prev);
          next.set(dirPath, result.entries);
          return next;
        });
        setError(null);
      }
    } catch (err) {
      if (mountedRef.current) {
        setError(err instanceof Error ? err.message : String(err));
      }
    }
  }, [agentName]);

  const toggle = useCallback(async (dirPath: string): Promise<void> => {
    setExpanded(prev => {
      const next = new Set(prev);
      if (next.has(dirPath)) {
        next.delete(dirPath);
      } else {
        next.add(dirPath);
      }
      return next;
    });

    // If expanding and not already cached, fetch
    if (!expanded.has(dirPath) && !treeData.has(dirPath)) {
      await loadDir(dirPath);
    }
  }, [expanded, treeData, loadDir]);

  const selectFile = useCallback((filePath: string | null) => {
    setSelectedPath(filePath);
  }, []);

  // --- Auto-load root on mount / agent change ---
  useEffect(() => {
    if (!agentName) return;
    setIsLoading(true);
    setExpanded(new Set());
    setTreeData(new Map());
    setSelectedPath(null);
    setError(null);

    listWorktreeDir(agentName)
      .then(result => {
        if (mountedRef.current) {
          setTreeData(new Map([["", result.entries]]));
          setExpanded(new Set([""]));
          setIsLoading(false);
        }
      })
      .catch(err => {
        if (mountedRef.current) {
          setError(err instanceof Error ? err.message : String(err));
          setIsLoading(false);
        }
      });
  }, [agentName]);

  return {
    expanded, treeData, selectedPath, isLoading, error,
    filterText, debouncedFilterText,
    toggle, loadDir, selectFile, setFilterText,
  };
}
```

**Note on `toggle` stale closure:** The `toggle` function reads `expanded` and `treeData` from closure. Since both are state values in the dependency array, `toggle` is recreated when they change. This is acceptable — `toggle` is only called on user click, not stored in long-lived refs. If the implementer prefers, they can use refs for `expanded`/`treeData` to stabilize the callback, but the simpler approach here matches the codebase's existing patterns.

### 2. `internal/webui/frontend/src/hooks/useFileContent.ts`

On-demand file content fetching hook, following `useIssueDetail` pattern.

```typescript
/**
 * useFileContent - React hook for fetching file content on demand.
 * Follows useIssueDetail pattern: requestIdRef for latest-wins, mountedRef for cleanup.
 */

import { useState, useCallback, useRef, useEffect } from "react";
import { readWorktreeFile } from "@/api/files";
import type { FileReadData } from "@/api/files";

export interface UseFileContentReturn {
  /** File content data, null if not loaded */
  fileData: FileReadData | null;
  /** Whether a fetch is currently in progress */
  isLoading: boolean;
  /** Error from the last fetch attempt, null if successful */
  error: string | null;
  /** Fetch content for a file by path */
  fetchFile: (path: string) => Promise<void>;
  /** Clear the current file content */
  clearFile: () => void;
}

export function useFileContent(agentName: string): UseFileContentReturn {
  const [fileData, setFileData] = useState<FileReadData | null>(null);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);

  const currentRequestIdRef = useRef<number>(0);
  const mountedRef = useRef<boolean>(true);

  useEffect(() => {
    mountedRef.current = true;
    return () => { mountedRef.current = false; };
  }, []);

  const fetchFile = useCallback(async (path: string): Promise<void> => {
    if (!path || !agentName) return;

    const requestId = ++currentRequestIdRef.current;

    setIsLoading(true);
    setError(null);

    try {
      const data = await readWorktreeFile(agentName, path);
      if (requestId === currentRequestIdRef.current && mountedRef.current) {
        setFileData(data);
        setError(null);
      }
    } catch (err) {
      if (requestId === currentRequestIdRef.current && mountedRef.current) {
        setError(err instanceof Error ? err.message : String(err));
      }
    } finally {
      if (requestId === currentRequestIdRef.current && mountedRef.current) {
        setIsLoading(false);
      }
    }
  }, [agentName]);

  const clearFile = useCallback(() => {
    currentRequestIdRef.current++;
    setFileData(null);
    setError(null);
    setIsLoading(false);
  }, []);

  return { fileData, isLoading, error, fetchFile, clearFile };
}
```

