func getOpenPRForBranch(dir, headBranch, baseBranch string) (string, error) {
    result := execCommand(dir, "gh", "pr", "list", "--head", headBranch, "--base", baseBranch, "--state", "open", "--json", "url", "--limit", "1")
    if result.Err != nil {
        return "", fmt.Errorf("gh pr list failed: %s", result.Stderr)
    }
    // Parse JSON: [{"url":"https://..."}] or []
    output := strings.TrimSpace(result.Stdout)
    if output == "" || output == "[]" {
        return "", nil
    }
    // Simple JSON extraction — avoid adding encoding/json dependency for a small struct
    // Actually, encoding/json is fine — it's stdlib
    type prInfo struct {
        URL string `json:"url"`
    }
    var prs []prInfo
    if err := json.Unmarshal([]byte(output), &prs); err != nil {
        return "", fmt.Errorf("parsing PR response: %v", err)
    }
    if len(prs) == 0 {
        return "", nil
    }
    return prs[0].URL, nil
}
```
