func buildPRBodyFromCommits(dir, sourceBranch, targetBranch string) string {
    output, err := RunGitCommand(dir, "log", fmt.Sprintf("%s..origin/%s", targetBranch, sourceBranch), "--oneline")
    if err != nil || strings.TrimSpace(output) == "" {
        return ""
    }
    var sb strings.Builder
    sb.WriteString("## Commits\n\n")
    for _, line := range strings.Split(strings.TrimSpace(output), "\n") {
        sb.WriteString(fmt.Sprintf("- %s\n", line))
    }
    sb.WriteString("\n---\n*Created by loom*\n")
    return sb.String()
}
