New:
```go
func(workspace, agent string) string {
    if workspaceConfigFn == nil {
        return ""
    }
    wsData, err := workspaceConfigFn()
    if err != nil || wsData == nil {
        return ""
    }
    if agent == "" {
        return ""
    }
    wsPath := wsData.Path
    candidate := filepath.Clean(filepath.Join(wsPath, "worktrees", agent))
    absBase, err := filepath.Abs(wsPath)
    if err != nil {
        return ""
    }
    absCandidate, err := filepath.Abs(candidate)
    if err != nil {
        return ""
    }
    if !strings.HasPrefix(absCandidate, absBase+string(filepath.Separator)) {
        return "" // agent name escapes workspace dir
    }
    os.MkdirAll(candidate, 0700)
    return candidate
},
```

Key changes:
- Returns `filepath.Join(wsPath, "worktrees", agent)` instead of `wsPath`
- Validates agent is non-empty
- Path traversal check ensures the resolved path stays under the workspace
- Creates the directory if needed (for lock file writes)
- Uses `filepath.Clean` to normalize `.` and `..` components before the check

