    data: WorkspaceData;
    warnings?: string[];
  }

  export async function createWorkspace(
    req: CreateWorkspaceRequest,
  ): Promise<CreateWorkspaceResult> {
    const response = await post<ApiResult<WorkspaceData>>("/api/workspace/create", req);
    // Keep unwrap for error handling, but also capture warnings
    if (!response.success) {
      throw new ApiError(0, response.error);
    }
    const data = response.data;
    cacheGeneration++;
    if (data) {
      workspaceCache = data;
    }
    fetchPromise = null;
    return {
      data: workspaceCache ?? (await refreshWorkspace()),
      warnings: response.warnings,
    };
  }
