// Apply custom workspace ordering if configured
if len(cfg.WorkspaceOrder) > 0 {
    orderIndex := make(map[string]int, len(cfg.WorkspaceOrder))
    for i, name := range cfg.WorkspaceOrder {
        orderIndex[name] = i
    }
    sort.SliceStable(summaries, func(i, j int) bool {
        oi, okI := orderIndex[summaries[i].Name]
        oj, okJ := orderIndex[summaries[j].Name]
        if okI && okJ {
            return oi < oj
        }
        if okI {
            return true // ordered items before unordered
        }
        if okJ {
            return false
        }
        return summaries[i].Name < summaries[j].Name // unordered items alphabetical
    })
} else {
    sort.Slice(summaries, func(i, j int) bool {
        return summaries[i].Name < summaries[j].Name
    })
}
