**Add PUT /api/workspace/order handler:**

```go
type workspaceOrderRequest struct {
    Order []string `json:"order"`
}

func handleWorkspaceReorder(configFn func() (*WorkspaceData, error)) http.HandlerFunc {
    return func(w http.ResponseWriter, r *http.Request) {
        var req workspaceOrderRequest
        if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
            respondJSON(w, http.StatusBadRequest, workspaceResponse{
                Success: false,
                Error:   "invalid request body",
            })
            return
        }

        // Load config, update workspace_order, save
        cfg, err := cli.LoadConfig()
        if err != nil || cfg == nil {
            respondJSON(w, http.StatusInternalServerError, workspaceResponse{
                Success: false,
                Error:   "failed to load config",
            })
            return
        }

        // Validate: only keep names that exist in cfg.Workspaces
        validOrder := make([]string, 0, len(req.Order))
        for _, name := range req.Order {
            if _, ok := cfg.Workspaces[name]; ok {
                validOrder = append(validOrder, name)
            }
        }
        cfg.WorkspaceOrder = validOrder

        if err := cli.SaveConfig(cfg); err != nil {
            respondJSON(w, http.StatusInternalServerError, workspaceResponse{
                Success: false,
                Error:   "failed to save config",
            })
            return
        }

        // Return updated workspace data
        data, err := configFn()
        if err != nil {
            respondJSON(w, http.StatusInternalServerError, workspaceResponse{
                Success: false,
                Error:   "failed to reload workspace data",
            })
            return
        }
        normalizeWorkspaceData(data)
        respondJSON(w, http.StatusOK, workspaceResponse{
            Success: true,
            Data:    data,
        })
    }
}
```

**Note on import cycle:** handlers_workspace.go is in package webui, and LoadConfig/SaveConfig are in package cli. If there's a circular import, the handler should accept a save callback (like configFn pattern) instead of importing cli directly. Check at implementation time and use a callback if needed:
