```tsx
const [workspaceOrder, setWorkspaceOrder] = useState<string[]>([]);

// Initialize order from API data (workspace_order or natural order)
useEffect(() => {
  if (workspace?.workspaces) {
    setWorkspaceOrder(workspace.workspaces.map(ws => ws.name));
  }
}, [workspace?.workspaces]);

// Reorder handler for drag-end
const handleDragEnd = useCallback((event: DragEndEvent) => {
  const { active, over } = event;
  if (!over || active.id === over.id) return;

  setWorkspaceOrder((prev) => {
    const oldIndex = prev.indexOf(active.id as string);
    const newIndex = prev.indexOf(over.id as string);
    const newOrder = arrayMove(prev, oldIndex, newIndex);
    // Persist to server (fire-and-forget with error rollback)
    reorderWorkspaces(newOrder).catch(() => setWorkspaceOrder(prev));
    return newOrder;
  });
}, []);

// Alt+Up/Down handlers
const handleMoveUp = useCallback((name: string) => {
  setWorkspaceOrder((prev) => {
    const idx = prev.indexOf(name);
    if (idx <= 0) return prev;
    const newOrder = arrayMove(prev, idx, idx - 1);
    reorderWorkspaces(newOrder).catch(() => setWorkspaceOrder(prev));
    return newOrder;
  });
}, []);

const handleMoveDown = useCallback((name: string) => {
  setWorkspaceOrder((prev) => {
    const idx = prev.indexOf(name);
    if (idx < 0 || idx >= prev.length - 1) return prev;
    const newOrder = arrayMove(prev, idx, idx + 1);
    reorderWorkspaces(newOrder).catch(() => setWorkspaceOrder(prev));
    return newOrder;
  });
}, []);

// Sensors with 5px activation distance (prevents accidental drags on click)
const sensors = useSensors(
  useSensor(PointerSensor, { activationConstraint: { distance: 5 } }),
  useSensor(KeyboardSensor),
);

// In JSX (after "All Workspaces" entry):
