const { repoAgents, unassignedAgents } = useMemo(() => {
  const grouped = new Map<string, LoomAgentStatus[]>();
  for (const repo of repos) {
    grouped.set(repo.name, []);
  }
  const unassigned: LoomAgentStatus[] = [];
  for (const agent of agents) {
