    var ct *ConcurrencyTracker
    counts := ct.Counts()
    if counts == nil {
        t.Error("nil Counts() returned nil, want empty map")
    }
    if len(counts) != 0 {
        t.Errorf("nil Counts() len = %d, want 0", len(counts))
