// Track previous sourceRepos for change detection
const prevSourceReposRef = useRef<string[] | undefined>(undefined);

useEffect(() => {
  // Skip on initial mount (autoConnect handles that)
  const prev = prevSourceReposRef.current;
  prevSourceReposRef.current = sourceRepos;

  // Only reconnect if sourceRepos actually changed (not initial mount)
  if (prev === undefined) return; // First render, skip

  // Compare arrays (order-insensitive would be overkill; simple join comparison)
  const prevKey = (prev ?? []).sort().join(",");
  const nextKey = (sourceRepos ?? []).sort().join(",");
  if (prevKey === nextKey) return;

  // Disconnect and reconnect with new source_repos
  const client = clientRef.current;
  if (client) {
    client.disconnect();
    // Small delay to allow clean disconnect before reconnect
    client.connect(sinceRef.current, sourceRepos);
  }
}, [sourceRepos]);
```
